import * as React from 'react';
import { getHostEndpoint } from './_endpoint';
/**
 * A React hook that returns a callback to refresh the Dashboard data surrounding the extension.
 *
 * @returns A stable callback function that triggers a Dashboard data refresh when invoked.
 * @public
 */
export const useRefreshDashboardData = () => {
    return React.useCallback(() => {
        return getHostEndpoint().call.refreshDashboardData();
    }, []);
};
